le (native strings lower to\\n   * `(ref null $AnyString)`). Absent ⇒ the historical lenient answer.\\n   */\\n  readonly stringIsExternref?: boolean;\\n\"\n          },\n          {\n            \"beforeStart\": 23246,\n            \"beforeEnd\": 23299,\n            \"beforeText\": \"      if (!returnTypeAssignable(actual, declared)) {\\n\",\n            \"currentStart\": 23618,\n            \"currentEnd\": 23699,\n            \"currentText\": \"      if (!returnTypeAssignable(actual, declared, options?.stringIsExternref)) {\\n\"\n          },\n          {\n            \"beforeStart\": 24737,\n            \"beforeEnd\": 24804,\n            \"beforeText\": \"        if (!returnTypeAssignable(actual, func.resultTypes[0]!)) {\\n\",\n            \"currentStart\": 25137,\n            \"currentEnd\": 25232,\n            \"currentText\": \"        if (!returnTypeAssignable(actual, func.resultTypes[0]!, options?.stringIsExternref)) {\\n\"\n          },\n          {\n            \"beforeStart\": 25815,\n            \"beforeEnd\": 25890,\n            \"beforeText\": \"function returnTypeAssignable(actual: IrType, declared: IrType): boolean {\\n\",\n            \"currentStart\": 26243,\n            \"currentEnd\": 26347,\n            \"currentText\": \"function returnTypeAssignable(actual: IrType, declared: IrType, stringIsExternref?: boolean): boolean {\\n\"\n          },\n          {\n            \"beforeStart\": 28284,\n            \"beforeEnd\": 28284,\n            \"beforeText\": \"\",\n            \"currentStart\": 28741,\n            \"currentEnd\": 29136,\n            \"currentText\": \"  // (#7001) A dynamic/externref value into a native-string result: string\\n  // lowers to `(ref null $AnyString)` there, so the flow needs a checked\\n  // conversion the IR does not emit. Only the host lane has string ≡ externref.\\n  if (\\n    declared.kind === \\\"string\\\" &&\\n    stringIsExternref === false &&\\n    (actual.kind === \\\"dynamic\\\" || a?.kind === \\\"externref\\\")\\n  ) {\\n    return false;\\n  }\\n\"\n          },\n          {\n            \"beforeStart\": 82195,\n            \"beforeEnd\": 82304,\n            \"beforeText\": \"  \\\"class.call\\\": { skip: \\\"resolver-typed: method signature resolved from the receiver's shape at lowering\\\" },\\n\",\n            \"currentStart\": 83047,\n            \"currentEnd\": 83151,\n            \"currentText\": \"  // (#7000) Target identity is checked; the signature stays resolver-typed.\\n  \\\"class.call\\\": \\\"checked\\\",\\n\"\n          },\n          {\n            \"beforeStart\": 89889,\n            \"beforeEnd\": 89889,\n            \"beforeText\": \"\",\n            \"currentStart\": 90736,\n            \"currentEnd\": 90827,\n            \"currentText\": \"    case \\\"class.call\\\":\\n      checkClassCallTarget(instr, blockId, ctx);\\n      return true;\\n\"\n          },\n          {\n            \"beforeStart\": 89929,\n            \"beforeEnd\": 89929,\n            \"beforeText\": \"\",\n            \"currentStart\": 90867,\n            \"currentEnd\": 92156,\n            \"currentText\": \"/**\\n * (#7000) `class.call` is a STATIC call of the member resolved on the\\n * receiver's class-shape chain (from-ast `findClassMember`). An exact `target`\\n * must be that member's own target: one bound to any other class's member is a\\n * wrong-body call (the devirtualisation drift #7000 fixed in the selector). A\\n * receiver that is not class-shaped, or a member the walk cannot see, stays\\n * resolver-typed and is not judged here.\\n */\\nfunction checkClassCallTarget(instr: IrInstrClassCall, blockId: number, ctx: RoadmapRuleCtx): void {\\n  const receiver = ctx.typeOf.get(instr.receiver);\\n  if (!instr.target || receiver?.kind !== \\\"class\\\") return;\\n  for (let shape: IrClassShape | undefined = receiver.shape; shape; shape = shape.parent) {\\n    const member = shape.methods.find(\\n      (candidate) => candidate.name === instr.methodName && (candidate.